import type { StoredSchedule } from '../types';
export type QuarantinedJob = StoredSchedule & {
    ownerId: string;
    enabled: boolean;
};
export interface ReconciliationJobStore {
    findOwnerTypes(): Promise<string[]>;
    findOwnerIds(ownerType: string, settledBefore: Date, limit: number, after?: string): Promise<string[]>;
    quarantineByOwnerIds(ownerType: string, ownerIds: string[], orphanedAt: Date, settledBefore: Date): Promise<number>;
    deleteQuarantinedByOwnerIds(ownerType: string, ownerIds: string[], quarantinedBefore: Date): Promise<number>;
    findQuarantinedByOwnerIds(ownerType: string, ownerIds: string[], limit: number): Promise<QuarantinedJob[]>;
    liftQuarantine(id: number, nextRunAt: Date | null): Promise<number>;
}
